{"implementation":"def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])
    by_id = {node["id"]: node for node in nodes}

    retained = {
        node["id"]
        for node in nodes
        if (not node["removable"])
        or node["symbol"] in required_symbols
        or node["utility"] >= 0.5
    }

    # Retaining a node also requires retaining its path to the root.
    pending = list(retained)
    while pending:
        node_id = pending.pop()
        parent_id = by_id[node_id]["parent"]
        if parent_id is not None and parent_id not in retained:
            retained.add(parent_id)
            pending.append(parent_id)

    return {
        "removed_node_ids": [
            node["id"] for node in nodes if node["id"] not in retained
        ],
        "retained_node_ids": [
            node["id"] for node in nodes if node["id"] in retained
        ],
    }
"}
